# Checks that the weight vector generated by pulp-nnx's HeaderWriter is 4-byte
# aligned when compiled against the testbench pmsis.h stub (issue #16).
#
# Usage: python model/test_weight_alignment.py  (CC selects the compiler)

import os
import shutil
import subprocess
import sys
import tempfile
import unittest

MODEL_DIR = os.path.dirname(os.path.abspath(__file__))
APP_INC_DIR = os.path.join(MODEL_DIR, "app", "inc")
sys.path.insert(0, os.path.join(MODEL_DIR, "deps", "pulp-nnx", "test"))

from HeaderWriter import HeaderWriter  # noqa: E402

CC = os.environ.get("CC") or shutil.which("gcc")

# A one-byte object is placed in .data_l1 right before the generated source, so
# the weight vector is not 4-byte aligned unless its declaration requires it.
PROBE = """\
#include <stdint.h>
#include <pmsis.h>

PI_L1 uint8_t leading_byte = 0x5a;

#include "weight.c"

#ifdef CHECK_ALIGNOF
_Static_assert(__alignof__(weight) >= 4, "weight is not 4-byte aligned");
#endif

int main(void) {
    return ((uintptr_t)weight % 4 == 0 && leading_byte == 0x5a) ? 0 : 1;
}
"""


@unittest.skipIf(CC is None, "no C compiler found (set CC)")
class WeightAlignmentTest(unittest.TestCase):
    def setUp(self):
        self.tmpdir = tempfile.mkdtemp()
        gendir = os.path.join(self.tmpdir, "gen")
        # Odd-sized weight so the compiler has no reason to over-align it.
        HeaderWriter(gendir).generate_vector_files(
            "weight", size=3, _type="uint8_t", init=[1, 2, 3]
        )
        self.probe = os.path.join(self.tmpdir, "probe.c")
        with open(self.probe, "w") as f:
            f.write(PROBE)
        self.cflags = [
            "-I" + APP_INC_DIR,
            "-I" + os.path.join(gendir, "inc"),
            "-I" + os.path.join(gendir, "src"),
        ]

    def tearDown(self):
        shutil.rmtree(self.tmpdir, ignore_errors=True)

    def compile(self, *args):
        return subprocess.run(
            [CC, *self.cflags, *args, self.probe],
            capture_output=True,
            text=True,
        )

    def test_weight_declaration_guarantees_alignment(self):
        result = self.compile("-DCHECK_ALIGNOF", "-fsyntax-only")
        self.assertEqual(result.returncode, 0, result.stderr)

    def test_weight_address_is_aligned(self):
        exe = os.path.join(self.tmpdir, "probe.exe")
        result = self.compile("-O0", "-o", exe)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(subprocess.run([exe]).returncode, 0)


if __name__ == "__main__":
    unittest.main(verbosity=2)
